from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from datetime import UTC, datetime


ENDPOINT = "https://api.openaq.org/v3/locations?limit=1"
CREDENTIAL_NAMES = ["OPENAQ_API_KEY"]


def result(*, ok: bool, status: str, summary: str, details: dict | None = None) -> dict:
    return {
        "schema_version": "access_probe.v1",
        "dataset_slug": os.environ.get("DATASET_SLUG", "openaq"),
        "provider": "openaq",
        "ok": ok,
        "status": status,
        "checked_at": datetime.now(UTC).isoformat(),
        "credential_names": CREDENTIAL_NAMES,
        "summary": summary,
        "details": details or {},
    }


def main() -> None:
    api_key = os.environ.get("OPENAQ_API_KEY") or os.environ.get("OPENAQ_KEY")
    timeout = int(os.environ.get("ACCESS_PROBE_TIMEOUT_SECONDS", "20"))

    if not api_key:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="missing_credentials",
                    summary="OpenAQ API key is missing. Set OPENAQ_API_KEY or OPENAQ_KEY.",
                )
            )
        )
        return

    request = urllib.request.Request(ENDPOINT, headers={"X-API-Key": api_key}, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            payload = json.loads(response.read().decode("utf-8"))
        result_count = len(payload.get("results", [])) if isinstance(payload, dict) else 0
        print(
            json.dumps(
                result(
                    ok=True,
                    status="verified",
                    summary=f"OpenAQ API key worked against a lightweight locations request; returned {result_count} result(s).",
                    details={"endpoint": ENDPOINT, "result_count": result_count},
                )
            )
        )
    except urllib.error.HTTPError as error:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="failed",
                    summary=f"OpenAQ access probe failed with HTTP {error.code}.",
                    details={"endpoint": ENDPOINT, "http_status": error.code},
                )
            )
        )
    except urllib.error.URLError as error:
        print(
            json.dumps(
                result(
                    ok=False,
                    status="failed",
                    summary="OpenAQ access probe failed before receiving a response.",
                    details={"reason": str(error.reason)},
                )
            )
        )


if __name__ == "__main__":
    main()
